#include "ee/detail/x86f/lookup.h"

const ee_ascii_char_t* ee_prv_x86f_lookup_prefix_str(ee_x86_prefix_type_t pref, ee_ascii_char_t* out, ee_size_t out_size) {

    switch (pref) {
    case EE_X86_PREFIX_LOCK:     return EE_OBFUSCATED_SL("\xA0\xA3\x36\x3F", out, out_size); /* lock */
    case EE_X86_PREFIX_REPNE:    return EE_OBFUSCATED_SL("\xBE\xA9\x25\x3A\x8D", out, out_size); /* repne */
    case EE_X86_PREFIX_REP:      return EE_OBFUSCATED_SL("\xBE\xA9\x25", out, out_size); /* rep */
    case EE_X86_PREFIX_HT:       return EE_OBFUSCATED_SL("\xA4\xB8", out, out_size); /* ht */
    case EE_X86_PREFIX_HNT:      return EE_OBFUSCATED_SL("\xA4\xA2\x21", out, out_size); /* hnt */
    case EE_X86_PREFIX_XACQUIRE: return EE_OBFUSCATED_SL("\xB4\xAD\x36\x25\x9D\x6D\x58\x24", out, out_size); /* xacquire */
    case EE_X86_PREFIX_XRELEASE: return EE_OBFUSCATED_SL("\xB4\xBE\x30\x38\x8D\x65\x59\x24", out, out_size); /* xrelease */
    case EE_X86_PREFIX_BND:      return EE_OBFUSCATED_SL("\xAE\xA2\x31", out, out_size); /* bnd */
    default: break;
    }

    return 0;
}

